<script setup lang="ts">
import { formatTanggalWib } from '~~/shared/utils/waktu'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '~/components/ui/card'
import { Button } from '~/components/ui/button'
import { Skeleton } from '~/components/ui/skeleton'
import type { Tables } from '~~/shared/types/database.types'
definePageMeta({ layout: 'dashboard', title: 'Detail kegiatan PIMPASA' })
const route = useRoute()
type DetailKegiatan = Omit<Tables<'laporan_pimpasa'>, 'foto_path' | 'pdf_path' | 'kantor_id'> & { kantor: string; desa: string; pegawai: string; jenis: string; foto_url: string | null; pdf_url: string | null }
const { data, pending, error, refresh } = await useAsyncData<DetailKegiatan>(`kanwil-kegiatan-${route.params.id}`, () => useApi()<DetailKegiatan>(`/api/kanwil/kegiatan/${route.params.id}`))
</script>
<template><div class="grid gap-5"><header><Button as-child variant="ghost" class="-ml-3"><NuxtLink to="/kanwil/kegiatan">← Kembali ke daftar</NuxtLink></Button><h2 class="mt-2 text-2xl font-semibold tracking-tight">Detail kegiatan PIMPASA</h2></header><div v-if="pending" class="grid gap-3"><Skeleton class="h-40 w-full" /><Skeleton class="h-64 w-full" /></div><Card v-else-if="error" role="alert"><CardHeader><CardTitle>Detail belum dapat dimuat</CardTitle><CardDescription>Periksa koneksi atau akses laporan kegiatan.</CardDescription></CardHeader><CardContent><Button variant="outline" @click="refresh()">Coba lagi</Button></CardContent></Card><template v-else-if="data"><Card><CardHeader><CardTitle>{{ data.jenis }}</CardTitle><CardDescription>{{ data.kantor }} · {{ formatTanggalWib(data.tanggal_kegiatan) }}</CardDescription></CardHeader><CardContent class="grid gap-5 sm:grid-cols-2"><div><p class="text-sm text-muted-foreground">Desa binaan</p><p class="font-medium">{{ data.desa }}</p></div><div><p class="text-sm text-muted-foreground">Petugas</p><p class="font-medium">{{ data.pegawai }}<span v-if="data.petugas_pengganti"> · Petugas pengganti</span></p></div><div><p class="text-sm text-muted-foreground">Jumlah peserta</p><p class="font-medium">{{ data.jumlah_peserta }}</p></div><div class="sm:col-span-2"><p class="text-sm text-muted-foreground">Uraian hasil</p><p class="mt-1 whitespace-pre-wrap leading-7">{{ data.uraian_hasil }}</p></div><div class="flex flex-wrap gap-3 sm:col-span-2"><a v-if="data.foto_url" :href="data.foto_url" target="_blank" rel="noopener noreferrer" class="text-sm font-medium underline">Buka foto</a><a v-if="data.pdf_url" :href="data.pdf_url" target="_blank" rel="noopener noreferrer" class="text-sm font-medium underline">Buka PDF laporan</a><p v-if="!data.foto_url && !data.pdf_url" class="text-sm text-muted-foreground">Tidak ada lampiran.</p></div></CardContent></Card></template></div></template>
